@using sv_87b9f6672eb74b9bb2c79251cceae6f6.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h2>Profile Settings</h2>

    @if (_loading)
    {
        <p class="loading">Loading profile...</p>
    }
    else
    {
        <div class="profile-form">
            <div class="avatar-preview">
                <div class="avatar-image">
                    @if (!string.IsNullOrEmpty(_avatarUrl))
                    {
                        <img src="@_avatarUrl" alt="Avatar" />
                    }
                    else
                    {
                        <span class="avatar-placeholder">👤</span>
                    }
                </div>
                <label class="form-label">Avatar URL</label>
                <input type="url" class="form-input" @bind="_avatarUrl" placeholder="https://example.com/avatar.png" />
            </div>

            <div class="form-group">
                <label class="form-label">Display Name</label>
                <input type="text" class="form-input" @bind="_displayName" placeholder="Your display name" />
            </div>

            <div class="form-group">
                <label class="form-label">Email</label>
                <input type="email" class="form-input" @bind="_email" placeholder="you@example.com" />
            </div>

            <div class="form-group">
                <label class="form-label">Bio</label>
                <textarea class="form-input form-textarea" @bind="_bio" placeholder="Tell us about yourself..."></textarea>
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                    @(_saving ? "Saving..." : "Save Changes")
                </button>
                <button class="btn btn-secondary" @onclick="Discard" disabled="@_saving">
                    Discard Changes
                </button>
            </div>

            @if (_showSuccess)
            {
                <div class="toast toast-success">Profile saved successfully!</div>
            }
        </div>
    }
</div>

@code {
    private string _displayName = "";
    private string _email = "";
    private string _avatarUrl = "";
    private string _bio = "";
    private UserProfile? _savedProfile;
    private bool _loading = true;
    private bool _saving;
    private bool _showSuccess;

    protected override async Task OnInitializedAsync()
    {
        await LoadProfileAsync();
    }

    private async Task LoadProfileAsync()
    {
        _loading = true;
        _savedProfile = await SettingsService.GetProfileAsync();
        ApplyProfile(_savedProfile);
        _loading = false;
    }

    private void ApplyProfile(UserProfile profile)
    {
        _displayName = profile.DisplayName;
        _email = profile.Email;
        _avatarUrl = profile.AvatarUrl;
        _bio = profile.Bio;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _showSuccess = false;
        var profile = new UserProfile(_displayName, _email, _avatarUrl, _bio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        _saving = false;
        _showSuccess = true;
        _ = HideToastAfterDelay();
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }

    private void Discard()
    {
        if (_savedProfile is not null)
        {
            ApplyProfile(_savedProfile);
        }
        _showSuccess = false;
    }
}
"}

