@using sv_87b9f6672eb74b9bb2c79251cceae6f6.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h2>Notification Preferences</h2>

    @if (_loading)
    {
        <p class="loading">Loading preferences...</p>
    }
    else
    {
        <div class="notifications-form">
            <div class="toggle-group">
                <label class="toggle-label">
                    <span class="toggle-switch">
                        <input type="checkbox" @bind="_emailNotifications" />
                        <span class="toggle-slider"></span>
                    </span>
                    <span>Email Notifications</span>
                </label>

                <label class="toggle-label">
                    <span class="toggle-switch">
                        <input type="checkbox" @bind="_pushNotifications" />
                        <span class="toggle-slider"></span>
                    </span>
                    <span>Push Notifications</span>
                </label>

                <label class="toggle-label">
                    <span class="toggle-switch">
                        <input type="checkbox" @bind="_weeklyDigest" />
                        <span class="toggle-slider"></span>
                    </span>
                    <span>Weekly Digest</span>
                </label>
            </div>

            <div class="channels-section">
                <h3>Muted Channels</h3>
                <div class="channel-list">
                    @foreach (var channel in _allChannels)
                    {
                        <label class="channel-item">
                            <input type="checkbox"
                                   checked="@_mutedChannels.Contains(channel)"
                                   @onchange="e => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                            <span>@channel</span>
                        </label>
                    }
                </div>
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                    @(_saving ? "Saving..." : "Save Preferences")
                </button>
            </div>

            @if (_showSuccess)
            {
                <div class="toast toast-success">Preferences saved successfully!</div>
            }
        </div>
    }
</div>

@code {
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private HashSet<string> _mutedChannels = new();
    private bool _loading = true;
    private bool _saving;
    private bool _showSuccess;

    private static readonly string[] _allChannels = { "General", "Announcements", "Engineering", "Design", "Marketing", "Support" };

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotifications = prefs.EmailNotifications;
        _pushNotifications = prefs.PushNotifications;
        _weeklyDigest = prefs.WeeklyDigest;
        _mutedChannels = new HashSet<string>(prefs.MutedChannels);
        _loading = false;
    }

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _showSuccess = false;
        var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, _mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _saving = false;
        _showSuccess = true;
        _ = HideToastAfterDelay();
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}
"}

{"path": "/tmp/sv-87b9f6672eb74b9bb2c79251cceae6f6/Components/Pages/Settings/SecuritySection.razor", "file_text": "@namespace sv_87b9f6672eb74b9bb2c79251cceae6f6.Components.Pages.Settings
@using sv_87b9f6672eb74b9bb2c79251cceae6f6.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h2>Security Settings</h2>

    @if (_loading)
    {
        <p class="loading">Loading security settings...</p>
    }
    else
    {
        <div class="security-form">
            <!-- Change Password Panel -->
            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                    <span>Change Password</span>
                    <span class="panel-toggle">@(_passwordPanelOpen ? "▲" : "▼")</span>
                </button>

                @if (_passwordPanelOpen)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label class="form-label">Current Password</label>
                            <input type="password" class="form-input" @bind="_currentPassword" />
                        </div>
                        <div class="form-group">
                            <label class="form-label">New Password</label>
                            <input type="password" class="form-input" @bind="_newPassword" />
                        </div>
                        <div class="form-group">
                            <label class="form-label">Confirm New Password</label>
                            <input type="password" class="form-input" @bind="_confirmPassword" />
                        </div>

                        @if (!string.IsNullOrEmpty(_passwordError))
                        {
                            <div class="toast toast-error">@_passwordError</div>
                        }
                        @if (_passwordSuccess)
                        {
                            <div class="toast toast-success">Password updated successfully!</div>
                        }

                        <button class="btn btn-primary" @onclick="ChangePasswordAsync" disabled="@_changingPassword">
                            @(_changingPassword ? "Updating..." : "Update Password")
                        </button>
                    </div>
                }
            </div>

            <!-- Two-Factor Authentication -->
            <div class="twofa-section">
                <h3>Two-Factor Authentication</h3>
                <div class="twofa-status">
                    <span class="status-indicator @(_twoFactorEnabled ? "status-enabled" : "status-disabled")"></span>
                    <span>@(_twoFactorEnabled ? "Enabled" : "Disabled")</span>
                    <label class="toggle-label">
                        <span class="toggle-switch">
                            <input type="checkbox" @bind="_twoFactorEnabled" />
                            <span class="toggle-slider"></span>
                        </span>
                    </label>
                </div>
                @if (_lastPasswordChange.HasValue)
                {
                    <p class="helper-text">Last password change: @_lastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                }
            </div>

            <!-- Active Sessions -->
            <div class="sessions-section">
                <h3>Active Sessions</h3>
                <table class="sessions-table">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th>Actions</th>
                        </tr>
                    </thead>
                    <tbody>
                        @foreach (var session in _sessions)
                        {
                            <tr>
                                <td>@session.Device</td>
                                <td>@session.Location</td>
                                <td>@session.LastActive.ToString("g")</td>
                                <td>
                                    @if (session != _sessions.FirstOrDefault())
                                    {
                                        <button class="btn btn-danger btn-sm" @onclick="() => ConfirmRevoke(session)">
                                            Revoke
                                        </button>
                                    }
                                    else
                                    {
                                        <span class="current-session-badge">Current</span>
                                    }
                                </td>
                            </tr>
                        }
                    </tbody>
                </table>
            </div>

            <!-- Revoke Confirmation Dialog -->
            @if (_sessionToRevoke is not null)
            {
                <div class="dialog-overlay">
                    <div class="dialog">
                        <h3>Revoke Session</h3>
                        <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> in <strong>@_sessionToRevoke.Location</strong>?</p>
                        <div class="dialog-actions">
                            <button class="btn btn-danger" @onclick="RevokeSessionAsync" disabled="@_revoking">
                                @(_revoking ? "Revoking..." : "Revoke")
                            </button>
                            <button class="btn btn-secondary" @onclick="() => _sessionToRevoke = null" disabled="@_revoking">
                                Cancel
                            </button>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
</div>

@code {
    private bool _loading = true;
    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _passwordError;
    private bool _passwordSuccess;
    private bool _changingPassword;
    private bool _twoFactorEnabled;
    private DateTime? _lastPasswordChange;
    private List<ActiveSession> _sessions = new();
    private ActiveSession? _sessionToRevoke;
    private bool _revoking;

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var settings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = settings.TwoFactorEnabled;
        _lastPasswordChange = settings.LastPasswordChange;
        _sessions = settings.Sessions;
        _loading = false;
    }

    private async Task ChangePasswordAsync()
    {
        _passwordError = null;
        _passwordSuccess = false;

        if (string.IsNullOrWhiteSpace(_newPassword))
        {
            _passwordError = "New password cannot be empty.";
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            _passwordError = "New password and confirmation do not match.";
            return;
        }

        _changingPassword = true;
        try
        {
            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
            _passwordSuccess = true;
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
        }
        catch (Exception ex)
        {
            _passwordError = ex.Message;
        }
        finally
        {
            _changingPassword = false;
        }
    }

    private void ConfirmRevoke(ActiveSession session)
    {
        _sessionToRevoke = session;
    }

    private async Task RevokeSessionAsync()
    {
        if (_sessionToRevoke is null) return;

        _revoking = true;
        await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
        _sessions.Remove(_sessionToRevoke);
        _sessionToRevoke = null;
        _revoking = false;
    }
}
"}

{"path": "/tmp/sv-87b9f6672eb74b9bb2c79251cceae6f6/Components/Pages/Settings/AppearanceSection.razor", "file_text": "@namespace sv_87b9f6672eb74b9bb2c79251cceae6f6.Components.Pages.Settings
@using sv_87b9f6672eb74b9bb2c79251cceae6f6.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h2>Appearance Settings</h2>

    @if (_loading)
    {
        <p class="loading">Loading appearance settings...</p>
    }
    else
    {
        <div class="appearance-form">
            <!-- Theme Selector -->
            <div class="form-group">
                <label class="form-label">Theme</label>
                <div class="radio-group">
                    @foreach (var theme in _themes)
                    {
                        <label class="radio-label">
                            <input type="radio" name="theme" value="@theme"
                                   checked="@(_theme == theme)"
                                   @onchange="() => _theme = theme" />
                            <span>@theme</span>
                        </label>
                    }
                </div>
            </div>

            <!-- Font Size Selector -->
            <div class="form-group">
                <label class="form-label">Font Size</label>
                <div class="radio-group">
                    @foreach (var size in _fontSizes)
                    {
                        <label class="radio-label">
                            <input type="radio" name="fontSize" value="@size"
                                   checked="@(_fontSize == size)"
                                   @onchange="() => _fontSize = size" />
                            <span>@size</span>
                        </label>
                    }
                </div>
            </div>

            <!-- Language Dropdown -->
            <div class="form-group">
                <label class="form-label">Language</label>
                <select class="form-input" @bind="_language">
                    @foreach (var lang in _languages)
                    {
                        <option value="@lang.Key">@lang.Value</option>
                    }
                </select>
            </div>

            <!-- Compact Mode -->
            <div class="form-group">
                <label class="toggle-label">
                    <span class="toggle-switch">
                        <input type="checkbox" @bind="_compactMode" />
                        <span class="toggle-slider"></span>
                    </span>
                    <span>Compact Mode</span>
                </label>
            </div>

            <!-- Live Preview -->
            <div class="preview-area @GetPreviewClasses()">
                <h4>Live Preview</h4>
                <p class="preview-text">This is how your content will look with the selected settings.</p>
                <div class="preview-card">
                    <strong>Sample Card</strong>
                    <p>A preview of the card component with your chosen appearance.</p>
                    <button class="preview-btn">Sample Button</button>
                </div>
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                    @(_saving ? "Saving..." : "Save")
                </button>
            </div>

            @if (_showSuccess)
            {
                <div class="toast toast-success">Appearance settings saved!</div>
            }
        </div>
    }
</div>

@code {
    private string _theme = "System";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;
    private bool _loading = true;
    private bool _saving;
    private bool _showSuccess;

    private static readonly string[] _themes = { "Light", "Dark", "System" };
    private static readonly string[] _fontSizes = { "Small", "Medium", "Large" };
    private static readonly Dictionary<string, string> _languages = new()
    {
        ["en"] = "English",
        ["es"] = "Español",
        ["fr"] = "Français",
        ["de"] = "Deutsch",
        ["ja"] = "日本語"
    };

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{_theme.ToLowerInvariant()} preview-font-{_fontSize.ToLowerInvariant()}";
        if (_compactMode) classes += " preview-compact";
        return classes;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _showSuccess = false;
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _saving = false;
        _showSuccess = true;
        _ = HideToastAfterDelay();
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}
"}

